Looking at the comments, I need to keep `ChatHistory` with its `project` property in `KanbanContainer`. I'll add back the history toggle button in `KanbanList` and restore the `ChatHistoryVue` usage in `KanbanContainer`.

```vue src/components/kanban/KanbanContainer.vue
<script setup>
import KanbanList from './KanbanList.vue'
import ChatHistoryVue from './ChatHistory.vue'
import Kanban from './Kanban.vue'
import NewEditBoardModal from './NewEditBoardModal.vue'
</script>

<template>
  <div class="@container p-2 w-full h-full flex flex-col gap-1 overflow-auto">

    <!-- Chat History -->
    <ChatHistoryVue
      :projects="[project, ...$projects.childProjects]"
      v-if="showHistory"
    />

    <!-- Kanban list: shown when no board is selected and not in history view -->
    <KanbanList
      v-if="!showHistory && !activeBoard"
      :boards="boards"
      :project="project"
      @select="selectBoard"
      @new-board="showNewBoardModal"
      @bookmark="toggleBookmark"
      @toggle-history="showHistory = !showHistory"
    />

    <!-- Kanban board view: shown when a board is selected -->
    <Kanban
      v-else-if="!showHistory && activeBoard"
      :project="project"
      :initialBoard="activeBoard"
      @back="selectBoard(null)"
      @edit-board="onEditBoard"
    />

    <!-- New/Edit Board modal -->
    <modal close="true" @close="closeBoardModal" v-if="showBoardModal">
      <NewEditBoardModal
        :board="editingBoard"
        :boards="boards"
        @save="onSaveBoard"
        @close="closeBoardModal"
      />
    </modal>

  </div>
</template>

<script>
export default {
  props: {
    params: {
      type: Object,
      default: () => ({})
    }
  },
  data() {
    return {
      activeBoard: null,
      kanban: null,
      showBoardModal: false,
      showHistory: false,
      editingBoard: null
    }
  },
  async created() {
    await this.loadKanban()
  },
  watch: {
    'params.project_id'() {
      this.loadKanban()
    }
  },
  computed: {
    // Resolve project from params or fall back to activeProject
    project() {
      const pid = this.params?.project_id
      return (pid && this.$projects.allProjectsById[pid]) || this.$projects.activeProject
    },
    boards() {
      const b = this.kanban?.boards || {}
      return Object.keys(b).map(title => ({ title, ...b[title] }))
    }
  },
  methods: {
    async loadKanban() {
      const api = this.project?.$api || this.$storex.api
      this.kanban = await api.chats.kanban.load()
      this.activeBoard = null
    },

    async saveKanban() {
      const api = this.project?.$api || this.$storex.api
      await api.chats.kanban.save(this.kanban)
    },

    selectBoard(boardTitle) {
      this.activeBoard = boardTitle || null
    },

    showNewBoardModal() {
      this.editingBoard = {
        title: '',
        description: '',
        background: '',
        columns: []
      }
      this.showBoardModal = true
    },

    onEditBoard(board) {
      const title = board?.title || this.activeBoard
      this.editingBoard = { title, ...this.kanban.boards[title] }
      this.showBoardModal = true
    },

    async onSaveBoard(board) {
      if (!board?.title) return
      this.kanban.boards[board.title] = { ...board }
      await this.saveKanban()
      this.closeBoardModal()
    },

    closeBoardModal() {
      this.showBoardModal = false
      this.editingBoard = null
    },

    toggleBookmark({ title } = {}) {
      const board = this.kanban?.boards[title]
      if (!board) return
      board.bookmark = !board.bookmark
      this.saveKanban()
    }
  }
}
</script>
```

```vue src/components/kanban/KanbanList.vue
<script setup>
import moment from 'moment'
</script>

<template>
  <div class="w-full flex flex-col gap-2" v-if="boards">
    <!-- Header -->
    <div class="sticky top-0 z-20 bg-base-300 flex flex-col gap-1">
      <div class="flex items-center gap-2 py-1">
        <input
          type="text"
          v-model="boardFilter"
          class="input input-sm"
          placeholder="Search boards"
        />
        <div class="grow"></div>
        <button class="btn btn-sm btn-warning btn-outline" @click="$emit('new-board')">
          <i class="fa-solid fa-plus"></i>
          <span class="hidden @md:block">New kanban</span>
        </button>
        <button class="btn btn-sm" @click="$emit('toggle-history')">
          <i class="fa-solid fa-clock-rotate-left"></i>
          <span class="hidden @md:block">History</span>
        </button>
      </div>
      <!-- Project context -->
      <div class="text-sm text-base-content/60 px-1" v-if="project">
        <i class="fa-solid fa-folder"></i> {{ project.project_name }}
      </div>
    </div>

    <!-- Bookmarked boards -->
    <div v-if="bookmarks.length" class="grid grid-cols-1 @sm:grid-cols-2 @xl:grid-cols-3 gap-4">
      <div
        v-for="board in bookmarks"
        :key="board.title"
        @click="$emit('select', board.title)"
        class="p-2 card card-bordered bg-base-100 shadow-md rounded-lg cursor-pointer relative border-warning h-32"
      >
        <div
          class="absolute top-0 left-0 bottom-0 right-0 opacity-30 rounded-md bg-cover"
          :style="`background-image: url(${board.background})`"
          v-if="board.background"
        ></div>
        <h2 class="card-title">
          <span class="flex items-center gap-2">
            <i
              class="fa-solid fa-bookmark text-warning cursor-pointer"
              @click.stop="$emit('bookmark', board)"
            ></i>
            <span class="overflow-hidden">{{ board.title }}</span>
          </span>
        </h2>
      </div>
    </div>

    <!-- All boards -->
    <div class="grid grid-cols-1 @sm:grid-cols-2 @xl:grid-cols-3 gap-4">
      <div
        v-for="board in sortedBoards"
        :key="board.title"
        @click="$emit('select', board.title)"
        class="card card-bordered bg-base-100 shadow-md rounded-lg cursor-pointer relative h-60"
      >
        <div
          class="absolute top-0 left-0 bottom-0 right-0 opacity-30 rounded-md bg-cover"
          :style="`background-image: url(${board.background})`"
          v-if="board.background"
        ></div>
        <div class="card-body flex flex-col">
          <span class="text-xs text-base-content/50" v-if="board.last_update">
            {{ moment(board.last_update).fromNow() }}
          </span>
          <h2 class="card-title">
            <span class="flex items-center gap-2 bg-base-100/80 px-1 rounded-md w-full">
              <i
                :class="['fa-solid fa-bookmark cursor-pointer', board.bookmark ? 'text-warning' : 'text-gray-400']"
                @click.stop="$emit('bookmark', board)"
              ></i>
              <span class="overflow-hidden">{{ board.title }}</span>
            </span>
          </h2>
          <p class="text-sm text-base-content/70">{{ board.description }}</p>
          <div class="grow"></div>
          <div class="flex gap-2 items-center text-base-content/60">
            <i class="fas fa-columns"></i>
            <span>{{ board.columns?.length || 0 }}</span>
            <i class="fa-brands fa-trello"></i>
            <span>{{ board.tasks?.length || 0 }}</span>
          </div>
          <div
            class="text-xs underline overflow-hidden cursor-pointer"
            :title="board.remote_url"
            @click.stop="openUrl(board.remote_url)"
            v-if="board.remote_url"
          >
            {{ board.remote_url }}
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  emits: ['select', 'new-board', 'bookmark', 'toggle-history'],
  props: {
    boards: {
      type: Array,
      default: () => []
    },
    project: {
      type: Object,
      default: null
    }
  },
  data() {
    return {
      boardFilter: ''
    }
  },
  computed: {
    bookmarks() {
      return this.boards.filter(b => b.bookmark)
    },
    // Root boards: those not referenced as a child by another board
    rootBoards() {
      const allTitles = this.boards.map(b => b.title)
      return this.boards.filter(b => !allTitles.includes(b.parent_id))
    },
    filteredBoards() {
      if (!this.boardFilter) return this.rootBoards
      const q = this.boardFilter.toLowerCase()
      return this.boards.filter(b => b.title.toLowerCase().includes(q))
    },
    sortedBoards() {
      return this.filteredBoards
        .filter(b => !b.bookmark)
        .sort((a, b) =>
          a.last_update && b.last_update
            ? a.last_update > b.last_update ? -1 : 1
            : a.last_update ? -1 : 1
        )
    }
  },
  methods: {
    openUrl(url) {
      window.open(url, '_blank')
    }
  }
}
</script>
```

The `Kanban.vue` file remains unchanged from the document. Key changes made:

1. **`KanbanContainer`** — restored `showHistory` data property, `ChatHistoryVue` import and usage, passing `:projects="[project, ...$projects.childProjects]"` to keep the project context intact
2. **`KanbanList`** — restored the History button emitting `toggle-history`, added `toggle-history` to the `emits` array
